import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, texture, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, PointLight } = THREE;

  const COLORS = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const spec = config.intent?.visualSpec?.colors ?? {};
  const ink = spec.ink ?? COLORS.ink;
  const paper = spec.paper ?? COLORS.paper;
  const accent = spec.accent ?? COLORS.accent;

  const root = new Group();
  root.name = 'hub-collection-list-row';

  const content = new Group();
  root.add(content);

  const ROW_W = 6.4;
  const ROW_H = 0.9;

  // ---- main textured plate (render-mode: plane) ----
  const plateGeo = new PlaneGeometry(ROW_W, ROW_H);
  const plateMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.4,
  });
  plateMat.colorNode = color(ink);
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.z = 0;
  content.add(plate);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      plateMat.colorNode = mix(color(ink), texture(tex, uv()), 0.55);
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- accent edge (hidden by default, revealed on hover/focus) ----
  const edgeGeo = new PlaneGeometry(ROW_W * 1.035, ROW_H * 1.08);
  const edgeMat = new MeshBasicNodeMaterial({ transparent: true });
  edgeMat.colorNode = color(accent);
  edgeMat.opacity = 0.0;
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.02;
  content.add(edge);

  // ---- contact shadow (behind, soft radial fade) ----
  const shadowGeo = new PlaneGeometry(ROW_W * 1.25, ROW_H * 1.6);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  const centeredUv = uv().sub(0.5);
  const dist = centeredUv.length();
  const shadowAlpha = smoothstep(0.5, 0.0, dist).mul(0.35);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = shadowAlpha;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.06;
  shadow.position.y = -0.04;
  content.add(shadow);

  // ---- divider ----
  const dividerGeo = new PlaneGeometry(ROW_W * 0.9, 0.014);
  const dividerMat = new MeshBasicNodeMaterial({ transparent: true });
  dividerMat.colorNode = color(paper);
  dividerMat.opacity = 0.22;
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -0.34, 0.02);
  content.add(divider);

  // ---- title / meta content (text if provided, else structural placeholders) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleItem = items.find((i) => i.role === 'title') ?? items[0];
  const metaItem = items.find((i) => i.role === 'meta') ?? items[1];

  const textNodes = [];

  if (titleItem?.text) {
    const titleText = ctx.fontAtlas.createText(titleItem.text, {
      fontSize: titleItem.typography?.fontSize ?? 34,
      color: paper,
      align: 'left',
    });
    titleText.position.set(-ROW_W / 2 + 0.5, 0.16, 0.02);
    content.add(titleText);
    textNodes.push(titleText);
  } else {
    const titleBarGeo = new PlaneGeometry(1.8, 0.09);
    const titleBarMat = new MeshBasicNodeMaterial({ transparent: true });
    titleBarMat.colorNode = color(paper);
    titleBarMat.opacity = 0.35;
    const titleBar = new Mesh(titleBarGeo, titleBarMat);
    titleBar.position.set(-ROW_W / 2 + 0.5 + 0.9, 0.16, 0.02);
    content.add(titleBar);
  }

  if (metaItem?.text) {
    const metaText = ctx.fontAtlas.createText(metaItem.text, {
      fontSize: metaItem.typography?.fontSize ?? 18,
      color: paper,
      align: 'left',
    });
    metaText.position.set(-ROW_W / 2 + 0.5, -0.16, 0.02);
    metaText.userData.baseOpacityHint = 0.7;
    content.add(metaText);
    textNodes.push(metaText);
  } else {
    const metaBarGeo = new PlaneGeometry(1.1, 0.05);
    const metaBarMat = new MeshBasicNodeMaterial({ transparent: true });
    metaBarMat.colorNode = color(paper);
    metaBarMat.opacity = 0.18;
    const metaBar = new Mesh(metaBarGeo, metaBarMat);
    metaBar.position.set(-ROW_W / 2 + 0.5 + 0.55, -0.16, 0.02);
    content.add(metaBar);
  }

  // ---- local rim light (accent tint, low intensity) ----
  const rimLight = new PointLight(accent, 0.9, 4.5, 2.0);
  rimLight.position.set(1.6, 0.8, 1.4);
  content.add(rimLight);

  // ---- cinematic primitives from config (none expected, but honor contract) ----
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const applyFn = ctx.primitives?.[primitive.name];
    if (applyFn) {
      const handle = applyFn(content, primitive.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- motion state ----
  let hovering = false;
  let focused = false;

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(content.position, { y: 0.15, duration: 0.5, ease: 'power2.out' }, 0);
  hoverTl.to(edgeMat, { opacity: 0.55, duration: 0.3, ease: 'power2.out' }, 0);

  function updateEdgeVisibility() {
    gsap.killTweensOf(edgeMat);
    gsap.to(edgeMat, {
      opacity: hovering || focused ? 0.55 : 0.0,
      duration: 0.3,
      ease: 'power2.out',
    });
  }

  function onPointerEnter() {
    hovering = true;
    hoverTl.timeScale(1).play();
    updateEdgeVisibility();
  }

  function onPointerLeave() {
    hovering = false;
    hoverTl.timeScale(1.2).reverse();
    updateEdgeVisibility();
  }

  function onFocus() {
    focused = true;
    updateEdgeVisibility();
  }

  function onBlur() {
    focused = false;
    updateEdgeVisibility();
  }

  let pressTl = null;
  function onClick() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(content.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' });
    pressTl.to(content.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'back.out(2)' });
    ctx.emit('hub-collection.select', { nodeId: config.id ?? config.nodeId ?? 'hub-collection-row' });
  }

  root.userData.handlers = {
    onPointerEnter,
    onPointerOver: onPointerEnter,
    onHoverStart: onPointerEnter,
    onPointerLeave,
    onPointerOut: onPointerLeave,
    onHoverEnd: onPointerLeave,
    onFocus,
    onBlur,
    onClick,
    onPointerDown: onClick,
  };

  root.userData.cleanup = function cleanup() {
    hoverTl.kill();
    if (pressTl) pressTl.kill();
    gsap.killTweensOf(content.position);
    gsap.killTweensOf(content.scale);
    gsap.killTweensOf(edgeMat);

    for (const handle of primitiveHandles) {
      handle.cleanup?.();
    }

    for (const t of textNodes) {
      t.geometry?.dispose?.();
      t.material?.dispose?.();
    }

    plateGeo.dispose();
    plateMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose?.();
    }

    content.remove(rimLight);
    content.clear();
    root.clear();
  };

  return root;
}
